fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // Ensure all inputs have the same length
    let n = condition.len();
    assert_eq!(x.len(), n, "x and condition must have the same length");
    assert_eq!(y.len(), n, "y and condition must have the same length");
    
    // Pre‐allocate the result vector
    let mut result = Vec::with_capacity(n);
    
    // Process each index in order, pushing the selected element
    for i in 0..n {
        if condition[i] {
            result.push(x[i]);
        } else {
            result.push(y[i]);
        }
    }
    
    result
}

